class BankAccount {
private:
    // Balance is hidden from outside access
    double balance;

public:
    // Constructor initializes the balance
    BankAccount(double init) : balance(init) {}

    // Controlled method to add funds
    void deposit(double amount) {
        // Only accept positive deposits
        if (amount > 0) balance += amount;
    }

    // Read-only getter for balance
    double getBalance() const {
        return balance;
    }
};

int main() {
    BankAccount myAcc(100.0);
    myAcc.deposit(50.0);
    return 0;
}

struct Vector3D {
    // Struct members are public by default
    float x;
    float y;
    float z;

    // Methods can still be added to structs
    float magnitude() {
        return sqrt(x*x + y*y + z*z);
    }
};

int main() {
    // Aggregate initialization maps directly to members
    Vector3D pos = {1.0, 2.0, 3.0};
    // Public access allows direct modification
    pos.x = 10.0;
    return 0;
}

// 'typename T' creates a generic type placeholder
template <typename T>
T getMax(T a, T b) {
    // This will work correctly for any compatible type
    return (a > b) ? a : b;
}

int main() {
    // Explicitly defining the type as int
    int i = getMax<int>(10, 20);

    // Compiler deduces 'float' automatically here
    float f = getMax(5.5f, 2.1f);

    return 0;
}

#include <iostream>
#include <vector>

int main() {
    std::vector<int> numbers;

    // Tracking memory geometry
    std::cout << "Initial capacity: " << numbers.capacity() << "\n";

    for (int i = 0; i < 5; i++) {
        numbers.push_back(i * 10);
        std::cout << "Size: " << numbers.size() 
                  << ", Capacity: " << numbers.capacity() << "\n";
    }

    // Shrinking capacity to fit the actual size
    numbers.shrink_to_fit();

    return 0;
}

#include <iostream>

// Base case to stop the template recursion
void printAll() {
    std::cout << "End of arguments\n";
}

// Recursive variadic template function
template <typename T, typename... Args>
void printAll(T first, Args... rest) {
    std::cout << first << ", ";

    // Recursive call expanding the parameter pack
    printAll(rest...);
}

int main() {
    printAll(10, "Hello", 3.14, 'A');
    return 0;
}

#include <iostream>
#include <deque>

int main() {
    std::deque<int> dq = { 20, 30, 40 };

    // O(1) insertion at the front
    dq.push_front(10);

    // O(1) insertion at the back
    dq.push_back(50);

    std::cout << "Front: " << dq.front() << "\n";
    std::cout << "Back:  " << dq.back() << "\n";

    // O(1) random access (slightly slower than vector)
    std::cout << "Item at index 2: " << dq[2] << "\n";

    return 0;
}

